/**
 * Vue から 1 つのエージェントの会話を使う composable。
 * 状態は shallowRef に入れ、スコープが終わると観測を止める。
 * SSR の間は接続を開かず、ブラウザでマウントしてから動き出す
 */
import {
	getCurrentInstance,
	getCurrentScope,
	type MaybeRefOrGetter,
	onMounted,
	onScopeDispose,
	shallowRef,
	toValue,
	watch,
} from "vue";
import {
	type AgentAbortResult,
	type AgentSendResult,
	type AgentSession,
	type AgentSnapshot,
	agentConversationUrl,
	type ConversationLiveMode,
	type CreateAgentSessionOptions,
	createAgentSession,
	emptyAgentSnapshot,
	type FlueClient,
	isBrowser,
	rememberedConversationId,
	type SendMessageOptions,
} from "./client";

export type {
	AgentSendResult,
	AgentSnapshot,
	AgentStatus,
	FailedSend,
	FlueConversationMessage,
	FlueConversationPart,
	SendMessageOptions,
} from "./client";

export type UseAgentOptions = {
	/**
	 * 会話の id。ref か getter を渡すと、変わったときに会話を切り替える。
	 * 省くと、ブラウザで乱数の id を作り、sessionStorage に覚える
	 */
	conversationId?: MaybeRefOrGetter<string | null | undefined>;
	/** 会話の URL の接頭辞。既定は Nuxt のモジュールか Vite のプラグインが rouar.json から入れた値 */
	route?: string;
	/** 会話の URL をそのまま渡す。name と conversationId より優先する */
	url?: MaybeRefOrGetter<string | null | undefined>;
	/** 作ってある会話のクライアント。url より優先する */
	client?: FlueClient;
	/** 観測の方式。既定は sse */
	live?: ConversationLiveMode;
	fetch?: CreateAgentSessionOptions["fetch"];
	headers?: CreateAgentSessionOptions["headers"];
};

export type UseAgentResult = AgentSnapshot & {
	/** 今の会話の URL。SSR の間とマウントの前は undefined */
	readonly url: string | undefined;
	sendMessage(
		message: string,
		options?: SendMessageOptions,
	): Promise<AgentSendResult>;
	/** 履歴を読み直し、観測をやり直す */
	refresh(): void;
	/** 会話の実行中と待ちの仕事を止める */
	abort(options?: { signal?: AbortSignal }): Promise<AgentAbortResult>;
};

function notOpen(): Error {
	return new Error(
		"[rouar] useAgent() has no open conversation. It opens in the browser after the component is mounted.",
	);
}

/**
 * エージェントの会話を観測し、送れるようにする。
 * 返す値は @flue/react の useFlueAgent と同じ形に abort と url を足したもの。
 * 項目は getter なので、分割代入せずに `agent.messages` の形で読む
 */
export function useAgent(
	name: MaybeRefOrGetter<string>,
	options: UseAgentOptions = {},
): UseAgentResult {
	const snapshot = shallowRef<AgentSnapshot>(emptyAgentSnapshot);
	const currentUrl = shallowRef<string | undefined>(undefined);
	let session: AgentSession | undefined;
	let unsubscribe: (() => void) | undefined;
	let stopWatch: (() => void) | undefined;
	let disposed = false;

	function close(): void {
		unsubscribe?.();
		unsubscribe = undefined;
		session?.dispose();
		session = undefined;
		currentUrl.value = undefined;
		snapshot.value = emptyAgentSnapshot;
	}

	function open(url: string | undefined): void {
		close();
		const next = createAgentSession({
			...(url !== undefined ? { url } : {}),
			...(options.client ? { client: options.client } : {}),
			...(options.live ? { live: options.live } : {}),
			...(options.fetch ? { fetch: options.fetch } : {}),
			...(options.headers ? { headers: options.headers } : {}),
		});
		if (!next) return;
		session = next;
		currentUrl.value = next.client.url;
		unsubscribe = next.subscribe(() => {
			snapshot.value = next.getSnapshot();
		});
		next.start();
		snapshot.value = next.getSnapshot();
	}

	function resolveUrl(): string | undefined {
		const explicit = toValue(options.url);
		if (explicit) return explicit;
		const agentName = toValue(name);
		const route = options.route;
		const conversationId =
			toValue(options.conversationId) ||
			rememberedConversationId(agentName, route ? { route } : {});
		if (!conversationId) return undefined;
		return agentConversationUrl(
			agentName,
			conversationId,
			route ? { route } : {},
		);
	}

	function begin(): void {
		if (disposed) return;
		if (options.client) {
			open(undefined);
			return;
		}
		stopWatch = watch(resolveUrl, (url) => open(url), { immediate: true });
	}

	// SSR の間は接続を開かない。マウントの前に状態を変えると、サーバーの描画と食い違うため、マウントを待つ
	if (isBrowser()) {
		const instance = getCurrentInstance();
		if (instance && !instance.isMounted) onMounted(begin);
		else begin();
	}

	if (getCurrentScope()) {
		onScopeDispose(() => {
			disposed = true;
			stopWatch?.();
			close();
		});
	}

	return {
		get messages() {
			return snapshot.value.messages;
		},
		get status() {
			return snapshot.value.status;
		},
		get historyReady() {
			return snapshot.value.historyReady;
		},
		get error() {
			return snapshot.value.error;
		},
		get failedSends() {
			return snapshot.value.failedSends;
		},
		get settlements() {
			return snapshot.value.settlements;
		},
		get url() {
			return currentUrl.value;
		},
		sendMessage(message, sendOptions) {
			return session
				? session.sendMessage(message, sendOptions)
				: Promise.reject(notOpen());
		},
		refresh() {
			session?.refresh();
		},
		abort(abortOptions) {
			return session ? session.abort(abortOptions) : Promise.reject(notOpen());
		},
	};
}
